/*
 * sw.js — NomadCare service worker (offline-first shell). Owner: P1 shell (PRECACHE regenerated by integrator).
 * Strategies:  HTML → network-first (3.5 s timeout) → cache → cached index.html
 *              same-origin static → cache-first (+ background refresh); on localhost/127.0.0.1 network-first
 *              offline vector basemap (assets/data/basemap/*.json, NOT precached) → network-first, offline from the
 *                page-managed cache 'nc-basemap-v1' (NC.basemap writes it; the worker never does)
 *              map tiles (CARTO / OSM) → stale-while-revalidate for VIEWED tiles only, capped at TILE_MAX entries
 *                (cache TILE_CACHE). A tile is cached only when it is verifiably a real tile (tileVerdict): never an
 *                opaque response, an OSM "Access blocked" tile (x-blocked / no-cache / known image), a CARTO
 *                "API key required" watermark (keyless URL / known image), an image that is not a ≥ 128 px square
 *                (1×1 / banner placeholders of blocking proxies — header dimensions, like mapkit.js suspectImage) or a
 *                non-image. A rejected revalidation never replaces a good cached tile. Blocked tiles reach the page
 *                as a 502 carrying 'x-nc-tile: blocked' so the map falls back (tileerror → vector basemap / notice).
 *                No tile prefetch / pre-seeding (OSM tile usage policy).
 *              Supabase, Open-Meteo, anything else cross-origin → network-only (not intercepted)
 * Messages: {type:'SKIP_WAITING'} · {type:'GET_VERSION'} (replies via MessageChannel) ·
 *           {type:'nc:cache-urls', urls:[…], cache:'static'} (same-origin static files only; replies {ok, cached, failed}) ·
 *           {type:'CLEAR_TILES'}
 * Update: install → skipWaiting, activate → clients.claim + purge old app caches AND old tile caches (a tile cache
 * written by an older worker may hold blocked / watermark tiles) → posts {type:'nc:sw-updated', version} to all
 * clients (app shows "Có phiên bản mới · Tải lại").
 */
'use strict';

const VERSION = 'nc-v2-6787e1ae';
const STATIC_CACHE = VERSION;              // versioned app shell cache ('nc-v2-<n>')
const TILE_CACHE = 'nc-tiles-v2';          // survives app updates; bump the suffix to purge every cached tile
const TILE_CACHE_PREFIX = 'nc-tiles';      // any other 'nc-tiles*' cache is purged on activate (old names: 'nc-tiles')
const BASEMAP_CACHE = 'nc-basemap-v1';     // offline vector basemap, written by NC.basemap (assets/js/services/basemap.js)
const BASEMAP_PATH = /\/assets\/data\/basemap\/[^/]+\.json$/;
const TILE_MAX = 600;
const NET_TIMEOUT_MS = 3500;
const IS_DEV = ['localhost', '127.0.0.1', '[::1]'].indexOf(self.location.hostname) >= 0;

