const TILE_HOSTS = /(^|\.)basemaps\.cartocdn\.com$|(^|\.)tile\.openstreetmap\.org$/;
const CARTO_HOST = /(^|\.)basemaps\.cartocdn\.com$/;
/* Fingerprints (byte length → SHA-256) of the known "not a map" tile images, captured 30/09/2026:
   OSM "403 Access blocked" (served with 200 + x-blocked + cache-control: no-cache) and the CARTO "API KEY REQUIRED"
   watermark (light + dark, served for keyless URLs). Same list in assets/js/services/mapkit.js (BLOCK_TILES). */
const BLOCK_TILES = {
  6987: ['b02c44252dac5a5e820ecef1e9bf9200e9407c042df668a466a1aa81a9ecca7a'],
  2049: ['69be4aecf9f814ba45d585801a5aa41e79b16fc88eafec5b1954a9f06a69e6be'],
  2513: ['cc3f31364a735d9a8179af36b3db7617cdff8bdb0248654ebcc3df91607abedc']
};
const NETWORK_ONLY_HOSTS = /(^|\.)supabase\.(co|in|net)$|(^|\.)open-meteo\.com$/;
const STATIC_EXT = /\.(?:css|js|mjs|json|webmanifest|svg|png|jpe?g|webp|gif|ico|woff2?|ttf|txt)$/i;

/* ------------------------------------------------------------------ */
/* Install: precache (tolerant — a missing file never breaks install)   */
/* ------------------------------------------------------------------ */
self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(STATIC_CACHE);
    await Promise.all(PRECACHE.map(async (url) => {
      try {
        // 'no-cache' = conditional request (ETag / Last-Modified): files the page has just downloaded come back as a
        // 304 served from the HTTP cache instead of a second full download ('reload' doubled first-visit transfer),
        // while a new release is still always revalidated against the server.
        const res = await fetch(new Request(url, { cache: 'no-cache' }));
        if (res && res.ok) await cache.put(url, res);
      } catch (e) { /* offline during install or 404 → skip */ }
    }));
    await self.skipWaiting();
  })());
});

/* ------------------------------------------------------------------ */
/* Activate: drop old versioned caches, claim clients, announce update  */
/* ------------------------------------------------------------------ */
self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    const old = keys.filter((k) => k.indexOf('nc-v2-') === 0 && k !== STATIC_CACHE);
    // Tile caches of older workers may hold OSM "Access blocked" / CARTO "API key required" images that were served
    // stale-first: drop them all (viewed tiles are simply fetched again, with a valid Referer, and re-validated).
    const oldTiles = keys.filter((k) => k.indexOf(TILE_CACHE_PREFIX) === 0 && k !== TILE_CACHE);
    await Promise.all(old.concat(oldTiles).map((k) => caches.delete(k)));
    await self.clients.claim();
    if (old.length) {
      const clients = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
      clients.forEach((c) => c.postMessage({ type: 'nc:sw-updated', version: VERSION }));
    }
    sweepTiles(); // not awaited: fetches are not held up while the cache is checked
  })());
});
/* An older worker may have stored placeholder "tiles" (1×1 / banner images with cacheable headers): drop every cached
   tile that is not a ≥ TILE_MIN_PX square; the good ones stay (offline they keep rendering). */
async function sweepTiles() {
  try {
    if (!(await caches.has(TILE_CACHE))) return;
    const cache = await caches.open(TILE_CACHE);
    for (const req of await cache.keys()) {
      const res = await cache.match(req);
      if (!res) continue;
      const size = imageSize(await res.arrayBuffer());
      if (size && (size.w < TILE_MIN_PX || size.h < TILE_MIN_PX || size.w !== size.h)) await cache.delete(req);
    }
  } catch (e) { /* best effort */ }
}

/* ------------------------------------------------------------------ */
/* Fetch routing                                                        */
/* ------------------------------------------------------------------ */
self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  let url;
  try { url = new URL(req.url); } catch (e) { return; }
  if (url.protocol !== 'http:' && url.protocol !== 'https:') return;

  if (NETWORK_ONLY_HOSTS.test(url.hostname)) return;                 // network-only
  if (TILE_HOSTS.test(url.hostname)) { event.respondWith(tileSWR(req, event)); return; }
  if (url.origin !== self.location.origin) return;                   // other cross-origin → browser default
  if (BASEMAP_PATH.test(url.pathname)) { event.respondWith(basemapFile(req)); return; }

  const isHTML = req.mode === 'navigate' || (req.headers.get('accept') || '').indexOf('text/html') >= 0;
  if (isHTML) { event.respondWith(networkFirstHTML(req)); return; }
  if (STATIC_EXT.test(url.pathname)) {
    event.respondWith(IS_DEV ? networkFirst(req) : cacheFirst(req, event));
  }
});

function timeoutFetch(req, ms) {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error('timeout')), ms);
    fetch(req).then((r) => { clearTimeout(timer); resolve(r); }, (e) => { clearTimeout(timer); reject(e); });
  });
}

async function networkFirstHTML(req) {
  const cache = await caches.open(STATIC_CACHE);
  try {
    const res = await timeoutFetch(req, NET_TIMEOUT_MS);
    if (res && res.ok) cache.put(req, res.clone());
    return res;
  } catch (e) {
    const hit = await cache.match(req, { ignoreSearch: true });
    if (hit) return hit;
    const shell = (await cache.match('./index.html')) || (await cache.match('./'));
    if (shell) return shell;
    return new Response('<h1>NomadCare offline</h1><p>Gọi 115 nếu khẩn cấp.</p>', { status: 503, headers: { 'Content-Type': 'text/html; charset=utf-8' } });
  }
}

async function cacheFirst(req, event) {
  const cache = await caches.open(STATIC_CACHE);
  const hit = await cache.match(req, { ignoreSearch: true });
  if (hit) {
    // refresh in the background so the next launch gets the latest file
    event.waitUntil(fetch(req).then((res) => { if (res && res.ok) return cache.put(req, res); }).catch(() => {}));
    return hit;
  }
  try {
    const res = await fetch(req);
    if (res && res.ok) cache.put(req, res.clone());
    return res;
  } catch (e) {
    return new Response('', { status: 504, statusText: 'offline' });
  }
}

async function networkFirst(req) {
  const cache = await caches.open(STATIC_CACHE);
  try {
    const res = await fetch(req);
    if (res && res.ok) cache.put(req, res.clone());
    return res;
  } catch (e) {
    const hit = await cache.match(req, { ignoreSearch: true });
    return hit || new Response('', { status: 504, statusText: 'offline' });
  }
}

/* Offline vector basemap: always the network while it answers (NC.basemap.download stores the file itself), else the
   copy the page saved in BASEMAP_CACHE. The worker never writes that cache (download = explicit user action). */
async function basemapFile(req) {
  try {
    const res = await fetch(req);
    if (res && (res.ok || res.status === 404)) return res;
    throw new Error('http ' + (res && res.status));
  } catch (e) {
    try {
      const cache = await caches.open(BASEMAP_CACHE);
      const hit = await cache.match(req, { ignoreSearch: true });
      if (hit) return hit;
    } catch (e2) { /* Cache API unavailable */ }
    return new Response('', { status: 504, statusText: 'basemap offline' });
  }
}

/* Tiles: stale-while-revalidate with a FIFO cap. Use L.tileLayer({crossOrigin:true}) to avoid opaque padding. */
let trimming = null;
async function trimTiles() {
  if (trimming) return trimming;
  trimming = (async () => {
    const cache = await caches.open(TILE_CACHE);
    const keys = await cache.keys();
    const excess = keys.length - TILE_MAX;
    for (let i = 0; i < excess; i++) await cache.delete(keys[i]);
  })().then(() => { trimming = null; }, () => { trimming = null; });
  return trimming;
}
function hex(buf) {
  const b = new Uint8Array(buf);
  let s = '';
  for (let i = 0; i < b.length; i++) s += (b[i] < 16 ? '0' : '') + b[i].toString(16);
  return s;
}
/**
 * Pixel size {w, h} of a PNG / GIF / WebP / JPEG body read from its header; null when the format is not recognised.
 * PNG: IHDR width / height (big-endian, bytes 16–23).
 */
function imageSize(buf) {
  const b = new Uint8Array(buf);
  const n = b.length;
  const u32 = (i) => ((b[i] << 24) >>> 0) + (b[i + 1] << 16) + (b[i + 2] << 8) + b[i + 3];
  if (n >= 24 && b[0] === 0x89 && b[1] === 0x50 && b[2] === 0x4e && b[3] === 0x47 &&
    b[12] === 0x49 && b[13] === 0x48 && b[14] === 0x44 && b[15] === 0x52) return { w: u32(16), h: u32(20) };
  if (n >= 10 && b[0] === 0x47 && b[1] === 0x49 && b[2] === 0x46 && b[3] === 0x38) return { w: b[6] | (b[7] << 8), h: b[8] | (b[9] << 8) };
  if (n >= 30 && b[0] === 0x52 && b[1] === 0x49 && b[2] === 0x46 && b[3] === 0x46 && b[8] === 0x57 && b[9] === 0x45 && b[10] === 0x42 && b[11] === 0x50) {
    const c = String.fromCharCode(b[12], b[13], b[14], b[15]);
    if (c === 'VP8 ') return { w: (b[26] | (b[27] << 8)) & 0x3fff, h: (b[28] | (b[29] << 8)) & 0x3fff };
    if (c === 'VP8L') { const x = (b[21] | (b[22] << 8) | (b[23] << 16) | (b[24] << 24)) >>> 0; return { w: (x & 0x3fff) + 1, h: ((x >>> 14) & 0x3fff) + 1 }; }
    if (c === 'VP8X') return { w: 1 + (b[24] | (b[25] << 8) | (b[26] << 16)), h: 1 + (b[27] | (b[28] << 8) | (b[29] << 16)) };
    return null;
  }
  if (n >= 4 && b[0] === 0xff && b[1] === 0xd8) { // JPEG: walk the segments to the first SOFn
    let i = 2;
    while (i + 8 < n) {
      if (b[i] !== 0xff) { i++; continue; }
      const m = b[i + 1];
      if (m === 0xff) { i++; continue; }
      if (m === 0x01 || (m >= 0xd0 && m <= 0xd8)) { i += 2; continue; }
      if (m >= 0xc0 && m <= 0xcf && m !== 0xc4 && m !== 0xc8 && m !== 0xcc) return { w: (b[i + 7] << 8) | b[i + 8], h: (b[i + 5] << 8) | b[i + 6] };
      i += 2 + ((b[i + 2] << 8) | b[i + 3]);
    }
    return null;
  }
  return null;
}
const TILE_MIN_PX = 128; // OSM / CARTO tiles are 256 or 512 px squares (same rule as mapkit.js suspectImage)
/**
 * Is this network response a real map tile worth caching?
 * 'ok' = cache it · 'nocache' = hand it to the page but do not store it (HTTP no-store / no-cache, opaque = cannot
 * be validated, OSM no-cache = typical of its error / block tiles) · 'blocked' = a known "not a map" image, a decoded
 * image that is not a ≥ TILE_MIN_PX square, a readable x-blocked header or a keyless CARTO URL (→ the page gets a
 * 502) · 'error' = not a usable response. A body too small to be suspicious by size is fine (an OSM sea tile is
 * ~100 bytes): the decision is made on the image dimensions, never on the byte count.
 * Pure apart from crypto.subtle (tests: tools/tests/basemap.test.js, tools/tests/map-qa.test.js).
 */
async function tileVerdict(req, res) {
  if (!res) return 'error';
  if (res.type === 'opaque') return 'nocache';
  if (!res.ok) return 'error';
  let url;
  try { url = new URL(req.url); } catch (e) { return 'error'; }
  if (CARTO_HOST.test(url.hostname) && !/[?&](key|api_key)=[^&]+/.test(url.search)) return 'blocked';
  const h = res.headers;
  if (h.get('x-blocked')) return 'blocked';
  const ct = h.get('content-type') || '';
  if (ct && !/^image\//i.test(ct)) return 'error';
  let buf;
  try { buf = await res.clone().arrayBuffer(); } catch (e) { return 'error'; }
  if (!buf || !buf.byteLength) return 'error';
  const known = BLOCK_TILES[buf.byteLength];
  if (known && self.crypto && self.crypto.subtle) {
    try {
      const sha = hex(await self.crypto.subtle.digest('SHA-256', buf));
      if (known.indexOf(sha) >= 0) return 'blocked';
    } catch (e) { /* no digest → fall through to the header rules */ }
  }
  const size = imageSize(buf);
  if (size && (size.w < TILE_MIN_PX || size.h < TILE_MIN_PX || size.w !== size.h)) return 'blocked';
  const cc = h.get('cache-control') || '';
  if (/no-store|no-cache|max-age=0\b/i.test(cc)) return 'nocache';
  return 'ok';
}
function blockedResponse() {
  return new Response('', { status: 502, statusText: 'Tile blocked', headers: { 'x-nc-tile': 'blocked', 'Cache-Control': 'no-store' } });
}
async function tileSWR(req, event) {
  const cache = await caches.open(TILE_CACHE);
  const hit = await cache.match(req);
  const refresh = fetch(req).then(async (res) => {
    const v = await tileVerdict(req, res);
    if (v === 'ok') { await cache.put(req, res.clone()); trimTiles(); }
    return v === 'blocked' ? blockedResponse() : res;
  }).catch(() => null);
  if (hit) {
    event.waitUntil(refresh);   // keep the worker alive while the cached tile is revalidated (a blocked answer never replaces it)
    return hit;
  }
  const res = await refresh;
  return res || new Response('', { status: 504, statusText: 'tile offline' });
}

/* ------------------------------------------------------------------ */
/* Messages                                                             */
/* ------------------------------------------------------------------ */
self.addEventListener('message', (event) => {
  const d = event.data || {};
  const reply = (msg) => { if (event.ports && event.ports[0]) event.ports[0].postMessage(msg); };
  if (d.type === 'SKIP_WAITING') { self.skipWaiting(); return; }
  if (d.type === 'GET_VERSION') { reply({ version: VERSION }); return; }
  if (d.type === 'CLEAR_TILES') {
    event.waitUntil(caches.keys().then((keys) => Promise.all(keys.filter((k) => k.indexOf(TILE_CACHE_PREFIX) === 0).map((k) => caches.delete(k))))
      .then(() => reply({ ok: true })));
    return;
  }
  // Bulk caching is for same-origin static files only. Tile prefetch / pre-seeding is deliberately NOT supported:
  // the OSM tile usage policy forbids it (offline maps use the vector basemap, assets/data/basemap/).
  if (d.type === 'nc:cache-urls' && Array.isArray(d.urls)) {
    if (d.cache !== 'static') { reply({ ok: false, error: 'tile_prefetch_disabled' }); return; }
    event.waitUntil((async () => {
      const cache = await caches.open(STATIC_CACHE);
      let cached = 0, failed = 0;
      for (const u of d.urls.slice(0, 200)) {
        try {
          const abs = new URL(u, self.location.href);
          if (abs.origin !== self.location.origin) { failed++; continue; }
          const res = await fetch(abs.href);
          if (res && res.ok) { await cache.put(abs.href, res); cached++; } else failed++;
        } catch (e) { failed++; }
      }
      reply({ ok: true, cached, failed });
    })());
  }
});

/* ------------------------------------------------------------------ */
/* Web Push + notification clicks (round 2 R6, owner W6)                */
/* ------------------------------------------------------------------ */
/* Push from the push-dispatch Edge Function: a generic reminder (no coordinates). When a window of the app is visible,
   the in-app popup of NC.trip already covers it: the page is only told to look again (no duplicate notification). */
const NC_ICON = new URL('assets/img/icons/icon-192.png', self.registration.scope).href;
/* Only windows of the traveller app count (the admin dashboard, docs or mockups on the same origin do not). */
const ncAppWindows = async () => {
  const scopePath = new URL(self.registration.scope).pathname;
  const wins = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
  return wins.filter((c) => {
    try { const p = new URL(c.url).pathname; return p === scopePath || p === scopePath + 'index.html'; } catch (e) { return false; }
  });
};
self.addEventListener('push', (event) => {
  let d = {};
  try { d = event.data ? event.data.json() : {}; } catch (e) { d = {}; }
  const title = typeof d.title === 'string' && d.title ? d.title.slice(0, 80) : 'NomadCare';
  const body = typeof d.body === 'string' ? d.body.slice(0, 200) : '';
  const tag = typeof d.tag === 'string' && /^nc-[a-z0-9.-]{1,40}$/.test(d.tag) ? d.tag : 'nc-dz';
  const url = new URL(typeof d.url === 'string' ? d.url : './#/map', self.registration.scope);
  const target = url.origin === self.location.origin ? url.href : new URL('./#/map', self.registration.scope).href;
  event.waitUntil((async () => {
    const wins = await ncAppWindows();
    const seen = wins.filter((c) => c.visibilityState === 'visible');
    if (seen.length) {
      seen.forEach((c) => c.postMessage({ type: 'nc:push', kind: d.kind || null, tag }));
      return;
    }
    await self.registration.showNotification(title, {
      body, tag, renotify: true, icon: NC_ICON, data: { url: target, kind: d.kind || null, key: null }
    });
  })());
});

/* A tap on a reminder (push or NC.trip's own notification): focus the app and show the popup, or open it. */
self.addEventListener('notificationclick', (event) => {
  const data = (event.notification && event.notification.data) || {};
  event.notification.close();
  const raw = typeof data.url === 'string' ? data.url : './?nc_alert=1#/map';
  let url;
  try { url = new URL(raw, self.registration.scope); } catch (e) { url = new URL('./#/map', self.registration.scope); }
  if (url.origin !== self.location.origin) url = new URL('./#/map', self.registration.scope);
  event.waitUntil((async () => {
    const wins = await ncAppWindows();
    const win = wins.find((c) => c.visibilityState === 'visible') || wins[0];
    if (win) {
      try { await win.focus(); } catch (e) { /* focus may be refused */ }
      win.postMessage({ type: 'nc:trip-alert', key: data.key || null, kind: data.kind || null });
      return;
    }
    if (!url.searchParams.has('nc_alert')) url.searchParams.set('nc_alert', data.key || '1');
    await self.clients.openWindow(url.href);
  })());
});
